package com.acme.payments;

import com.acme.payments.domain.AuthorizeRequest;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.annotation.Transactional;

import static org.junit.jupiter.api.Assertions.assertFalse;

class PaymentServiceTransactionTest {

    // Regression for inc-001: authorize() was @Transactional while calling
    // fraudClient.score() (and gateway.authorize()), so each slow fraud call
    // held one of only 10 Hikari connections and exhausted the pool.
    // Fails before the fix (annotation present), passes after it is removed;
    // persistence is then via each short repository save() transaction.
    @Test
    void authorizeDoesNotHoldTransactionAcrossRemoteCalls() throws Exception {
        boolean transactional = PaymentService.class
                .getMethod("authorize", AuthorizeRequest.class)
                .isAnnotationPresent(Transactional.class);
        assertFalse(transactional,
            "authorize() must not be @Transactional: it calls fraud/gateway " +
            "remotely and would hold a DB connection for their full duration");
    }
}

